begin;
set local search_path=public,extensions;
select plan(43);

select has_table('public','assistance_model_versions','assistance rules are versioned');
select has_table('public','assistance_profile_reassessments','profile changes create a reassessment queue');
select has_table('public','assistance_requests','bounded assistance requests are durable');
select has_table('public','assistance_suggestions','explainable suggestions are durable');
select has_table('public','assistance_suggestion_decisions','human decisions are append-only evidence');
select has_function('private','assistance_tokens',array['text'],'deterministic tokenizer exists');
select has_function('private','assistance_overlap_basis_points',array['text','text'],'version-neutral exact similarity exists');
select has_function('public','run_assisted_analysis',array['uuid','text','text','uuid[]','uuid[]','text[]','uuid','uuid','text','uuid'],'bounded assisted analysis command exists');
select has_function('public','decide_assisted_suggestion',array['uuid','text','text','text','uuid'],'human decision command exists');
select has_trigger('public','client_profile_versions','client_profile_assistance_reassessment','profile versions trigger proactive reassessment');

select col_type_is('public','assistance_suggestions','score_basis_points','integer','similarity uses bounded integer basis points');
select col_type_is('public','assistance_requests','candidate_service_version_ids','uuid[]','service candidates are caller-bounded identifiers');
select col_type_is('public','assistance_requests','candidate_question_version_ids','uuid[]','question candidates are caller-bounded identifiers');
select ok((select count(*)=0 from information_schema.columns where table_schema='public'and table_name like'assistance_%'and data_type in('real','double precision')),'assistance schema uses no floating point values');
select ok((select count(*)=5 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname in('assistance_model_versions','assistance_profile_reassessments','assistance_requests','assistance_suggestions','assistance_suggestion_decisions')and c.relrowsecurity),'all assistance tables enforce RLS');
select ok((select count(*)=5 from pg_policies where schemaname='public'and tablename in('assistance_model_versions','assistance_profile_reassessments','assistance_requests','assistance_suggestions','assistance_suggestion_decisions')),'every assistance table has an explicit read policy');
select ok((select count(*)=4 and bool_and(qual like'%organization_id%'and qual like'%assistance_role_access%'and qual not like'%is_active_org_member%')and count(*)filter(where qual like'%''READ''%')=3 and count(*)filter(where qual like'%''DECIDE''%')=1 from pg_policies where schemaname='public'and tablename in('assistance_profile_reassessments','assistance_requests','assistance_suggestions','assistance_suggestion_decisions')),'tenant policies enforce explicit least-privilege assistance roles instead of membership alone');
select ok(not has_table_privilege('authenticated','public.assistance_requests','INSERT')and not has_table_privilege('authenticated','public.assistance_suggestions','UPDATE')and not has_table_privilege('service_role','public.assistance_suggestion_decisions','DELETE'),'direct and service-role mutations are denied');
select ok(has_function_privilege('authenticated','public.run_assisted_analysis(uuid,text,text,uuid[],uuid[],text[],uuid,uuid,text,uuid)','EXECUTE')and has_function_privilege('authenticated','public.decide_assisted_suggestion(uuid,text,text,text,uuid)','EXECUTE'),'authenticated actors use governed commands');
select ok(not has_function_privilege('anon','public.run_assisted_analysis(uuid,text,text,uuid[],uuid[],text[],uuid,uuid,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.decide_assisted_suggestion(uuid,text,text,text,uuid)','EXECUTE'),'anonymous and service roles cannot invoke assistance commands');
select ok((select bool_and(p.prosecdef and p.proconfig::text like'%search_path=pg_catalog%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('run_assisted_analysis','decide_assisted_suggestion')),'public commands are security definer with fixed search paths');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%cardinality(coalesce(p_candidate_service_version_ids%>50%'and string_agg(p.prosrc,' ')like'%cardinality(coalesce(p_candidate_question_version_ids%>50%'and string_agg(p.prosrc,' ')like'%candidate_limit%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname='run_assisted_analysis_core_v1')),'analysis is bounded and cannot scan the full catalogue');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%v.id=any(coalesce(p_candidate_service_version_ids%'and string_agg(p.prosrc,' ')like'%v.id=any(coalesce(p_candidate_question_version_ids%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname='run_assisted_analysis_core_v1')),'analysis only reads explicitly targeted candidates');
select ok((select count(*)=3 and string_agg(p.prosrc,' ')like'%SERVICE_CANDIDATE%'and string_agg(p.prosrc,' ')like'%MISSING_QUESTION%'and string_agg(p.prosrc,' ')like'%confirmation_required%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname in('run_assisted_analysis_runtime_v2','run_assisted_analysis_core_v1'))),'free text proposes candidate services and missing questions with confirmation');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%QUESTION_AMBIGUITY%'and string_agg(p.prosrc,' ')like'%KNOWN_DATA_DUPLICATION%'and string_agg(p.prosrc,' ')like'%SEMANTIC_DUPLICATE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname='run_assisted_analysis_core_v1')),'quality analysis covers ambiguity known data and semantic duplicates');
select ok((select count(*)=3 and string_agg(p.prosrc,' ')like'%human_review_required%'and string_agg(p.prosrc,' ')like'%HUMAN_COMPARE%'and string_agg(p.prosrc,' ')not like'%update public.catalog_%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname in('run_assisted_analysis_runtime_v2','run_assisted_analysis_core_v1'))),'analysis is explainable and never mutates catalogue business objects');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%business_action_executed%false%'and string_agg(p.prosrc,' ')not like'%update public.catalog_%'and string_agg(p.prosrc,' ')not like'%insert into public.financial_%'and string_agg(p.prosrc,' ')not like'%insert into public.credit_%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='decide_assisted_suggestion')or(n.nspname='private'and p.proname='decide_assisted_suggestion_core_v1')),'accepting a suggestion never performs a critical autonomous action');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%begin_contract_command%'and string_agg(p.prosrc,' ')like'%finish_contract_command%'and string_agg(p.prosrc,' ')like'%audit_events%'and string_agg(p.prosrc,' ')like'%event_outbox%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname='run_assisted_analysis_core_v1')),'analysis is idempotent audited and emits Outbox');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%begin_contract_command%'and string_agg(p.prosrc,' ')like'%finish_contract_command%'and string_agg(p.prosrc,' ')like'%audit_events%'and string_agg(p.prosrc,' ')like'%event_outbox%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='decide_assisted_suggestion')or(n.nspname='private'and p.proname='decide_assisted_suggestion_core_v1')),'human decisions are idempotent audited and emit Outbox');
select ok((select p.prosrc like'%profile_data->x.key is distinct from%'and p.prosrc like'%assistance_profile_reassessments%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='enqueue_profile_assistance_reassessment'),'profile changes compare keys and enqueue reevaluation without copying values');
select ok((select p.prosrc not like'%profile_data::text%'and p.prosrc not like'%organization_snapshot%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='enqueue_profile_assistance_reassessment'),'profile queue does not persist sensitive profile values');
select ok((select count(*)=2 and string_agg(p.prosrc,' ')like'%status=''PENDING''for update%'and string_agg(p.prosrc,' ')like'%status=''COMPLETED''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname='run_assisted_analysis_core_v1')),'profile reassessments use a locked lifecycle');
select ok(exists(select 1 from information_schema.check_constraints where constraint_name in(select constraint_name from information_schema.constraint_column_usage where table_schema='public'and table_name='assistance_suggestions'and column_name='status')and check_clause like'%PROPOSED%'and check_clause like'%ACCEPTED%'and check_clause like'%REJECTED%'),'suggestion states are constrained');
select ok(exists(select 1 from information_schema.check_constraints where constraint_name in(select constraint_name from information_schema.constraint_column_usage where table_schema='public'and table_name='assistance_suggestion_decisions'and column_name='decision')and check_clause like'%ACCEPTED%'and check_clause like'%REJECTED%'),'human decisions are constrained');
select ok((select count(*)=3 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname in('assistance_model_versions','assistance_requests','assistance_suggestion_decisions')and not t.tgisinternal and t.tgname like'%immutable'),'model request and decision evidence are immutable');
select ok((select p.prosrc like'%ASSISTANCE_MODEL_CONTENT_IMMUTABLE%'and p.prosrc not like'%new.status%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='protect_assistance_model_version'),'model content is immutable while lifecycle supersession remains possible');
select has_index('public','assistance_model_versions','assistance_one_active_model_idx','only one active model version exists per model key');
select has_index('public','assistance_profile_reassessments','assistance_reassessment_queue_idx','profile reassessment queue is indexed');
select has_index('public','assistance_suggestions','assistance_suggestions_review_idx','human review queue is indexed');
select has_index('public','assistance_suggestions','assistance_suggestions_target_idx','similarity targets are indexed');
select ok((select provider_kind='DETERMINISTIC'and algorithm='TOKEN_OVERLAP_V1'and status='ACTIVE'from public.assistance_model_versions where id='a1000000-0000-4000-8000-000000000001'),'baseline engine is deterministic provider-neutral and versioned');
select ok((select configuration->>'candidate_limit'='10'and(configuration->>'duplicate_score_basis_points')::integer between 0 and 10000 from public.assistance_model_versions where id='a1000000-0000-4000-8000-000000000001'),'baseline thresholds are data-driven and bounded');
select ok((select count(*)=3 and string_agg(p.prosrc,' ')not like'%http%'and string_agg(p.prosrc,' ')not like'%openai%'and string_agg(p.prosrc,' ')not like'%anthropic%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='public'and p.proname='run_assisted_analysis')or(n.nspname='private'and p.proname in('run_assisted_analysis_runtime_v2','run_assisted_analysis_core_v1'))),'analysis has no external LLM dependency');

select * from finish();
rollback;
